<script lang="ts">
  import { goto } from '$app/navigation'; import { api } from '$lib/api'; import { apiError } from '$lib/student-session';
  let username = ''; let password = ''; let remember = false; let error = ''; let loading = false;
  async function submit() { loading = true; error = ''; try { const result = await api<any>('/api/student/auth/login', { method: 'POST', body: JSON.stringify({ username, password, rememberMe: remember }) }); await goto(result.disclaimerRequired ? '/student/disclaimer' : '/student'); } catch (e) { error = apiError(e, 'Sign-in failed.'); } finally { loading = false; } }
</script>
<svelte:head><title>Task Karate | Student sign-in</title></svelte:head>
<main class="auth-stage"><section class="auth-frame"><a class="brand" href="/schedule"><span class="brand-mark">TK</span><span><strong>TASK KARATE</strong><small>STUDENT HUB</small></span></a><span class="student-eyebrow">SECURE STUDENT ACCESS</span><h1>Enter the dojo.</h1><p class="lead">Use the account issued by Task Karate staff. Your session is protected by the server—not by a browser PIN.</p>{#if error}<div class="error" role="alert">{error}</div>{/if}<form on:submit|preventDefault={submit}><label>Username<input bind:value={username} autocomplete="username" required /></label><label>Password<input type="password" bind:value={password} autocomplete="current-password" required /></label><label class="check-row"><input type="checkbox" bind:checked={remember} /> Keep me signed in on this device</label><button class="primary-button wide" disabled={loading}>{loading ? 'Signing in…' : 'Sign in securely'}</button></form><a class="text-link" href="/schedule">← Back to schedule</a></section></main>
